function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value is an integer from 0 to 100.';
  return null;
}

