function distinctAverages(nums) {
  nums.sort((a, b) => a - b);
  const sums = new Set();
  let left = 0;
  let right = nums.length - 1;
  while (left < right) {
    sums.add(nums[left] + nums[right]);
    left++;
    right--;
  }
  return sums.size;
}

