function distinctAverages(nums) {
  const rest = nums.slice();
  const averages = [];
  while (rest.length > 0) {
    const low = Math.min(...rest);
    rest.splice(rest.indexOf(low), 1);
    const high = Math.max(...rest);
    rest.splice(rest.indexOf(high), 1);
    const avg = (low + high) / 2;
    if (!averages.includes(avg)) averages.push(avg);
  }
  return averages.length;
}

