function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = rand() < 0.5 ? 100 : pick(5, 30);
    return [Array.from({ length: 100 }, () => pick(0, top))];
  }
  const n = 2 * pick(1, 5);
  const top = rand() < 0.5 ? pick(1, 6) : 100;
  return [Array.from({ length: n }, () => pick(0, top))];
}
